(6456335, 959055, 124815, '<td valign="top">The dreamy determination of the solitary horse. Top 5</td>', 'The dreamy determination of the solitary horse. Top 5', '2011-06-30 01:24:38.000000', NULL, 1),
(6456336, 958769, 124815, '<td valign="top">A bit chalky but certainly a good image for a challenge that was somehow misunderstood. But I cannot stop thinking why such a great sunflower was not captured in color? Well, of course to respond to the challenge. A vicious circle. Anyway, top 5</td>', 'A bit chalky but certainly a good image for a challenge that was somehow misunderstood. But I cannot stop thinking why such a great sunflower was not captured in color? Well, of course to respond to the challenge. A vicious circle. Anyway, top 5', '2011-06-30 01:24:42.000000', NULL, 1),
(6456337, 959016, 124815, '<td valign="top">Yes. High Key all right! One of the few. And standing on its own.</td>', 'Yes. High Key all right! One of the few. And standing on its own.', '2011-06-30 01:24:44.000000', NULL, 1),
(6456338, 959184, 124815, '<td valign="top">Good title for a good image in a hard challenge</td>', 'Good title for a good image in a hard challenge', '2011-06-30 01:24:48.000000', NULL, 1),
(6456339, 958993, 124815, '<td valign="top">One of the very few IMO High Key images. Top 5</td>', 'One of the very few IMO High Key images. Top 5', '2011-06-30 01:24:54.000000', NULL, 1),
(6456342, 959220, 124815, '<td valign="top">Could be a lovely picture but it''s so washed out to respond to the High Key that it''s losing the appeal. Very hard to do a true High Key without falling into this trap. 6</td>', 'Could be a lovely picture but it''s so washed out to respond to the High Key that it''s losing the appeal. Very hard to do a true High Key without falling into this trap. 6', '2011-06-30 01:27:18.000000', NULL, 1),
