(6456566, 959211, 54033, '<td valign="top">Oh this is I!! <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=54033" rel="nofollow" target="_blank">highnooner</a> 10!</td>', 'Oh this is I!!  highnooner 10!', '2011-06-30 10:29:20.000000', NULL, 1),
