INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6459819, 958143, 96751, '<td valign="top">There is so much wrong with this image that it''s perfect.  Incredibly appealing for mysterious reasons I cannot explain.</td>', 'There is so much wrong with this image that it''s perfect.  Incredibly appealing for mysterious reasons I cannot explain.', '2011-07-03 13:48:08.000000', NULL, 1),
(6459823, 959213, 96751, '<td valign="top">Terrific, except the slightly angled pencil is driving me nuts.  More or less, but just a little bugs me.</td>', 'Terrific, except the slightly angled pencil is driving me nuts.  More or less, but just a little bugs me.', '2011-07-03 13:51:32.000000', NULL, 1),
(6459824, 959042, 96751, '<td valign="top">Supremely eerie and engrossing.</td>', 'Supremely eerie and engrossing.', '2011-07-03 13:51:55.000000', NULL, 1),
(6459826, 959184, 96751, '<td valign="top">Surreal.  Makes me stop and contemplate on the many levels and layers.  As though she''s being erased, one scratch at a time.</td>', 'Surreal.  Makes me stop and contemplate on the many levels and layers.  As though she''s being erased, one scratch at a time.', '2011-07-03 13:52:38.000000', NULL, 1),
(6460023, 958897, 38162, '<td valign="top">a big white border doesnt sell high key - your image did.</td>', 'a big white border doesnt sell high key - your image did.', '2011-07-03 19:51:09.000000', NULL, 1),
(6460025, 958863, 38162, '<td valign="top">border is just so unnecessary.  great concept.  gl</td>', 'border is just so unnecessary.  great concept.  gl', '2011-07-03 19:53:55.000000', NULL, 1),
(6460152, 959198, 18778, '<td valign="top">A beautiful portrait- your subject''s gaze is penetrating.  Howeves- this doesn''t feel HK for me- specifically the vignette doesn''t flow with that</td>', 'A beautiful portrait- your subject''s gaze is penetrating.  Howeves- this doesn''t feel HK for me- specifically the vignette doesn''t flow with that', '2011-07-03 23:19:08.000000', NULL, 1),
(6460156, 958571, 18778, '<td valign="top">No doubt- a beautiful capture.  But I''m just not feeling any sort of independent spirit here.  Feels like I''ve seen this before.  It''s very ''Gerogia O'' Keeffe''</td>', 'No doubt- a beautiful capture.  But I''m just not feeling any sort of independent spirit here.  Feels like I''ve seen this before.  It''s very ''Gerogia O'' Keeffe''', '2011-07-03 23:24:52.000000', NULL, 1),
(6460160, 959213, 18778, '<td valign="top">Oh. My. As a make up artist- I''m instantly drawn to this image.  I realize this challenge was basic editing but I''m DYING to fix her brows, the smudge on the left eye, straighten the pencil...but enough about my OCD.  I love the lines of this image- the way she dominates the left hand side while the kohl liner takes my eye to the other edge of the image.  I like the way the ''blacks'' in this image all complement each.  Brows framing the eyes, outlined by the lashes all underlined by the pencil.  It works for me.  Well done.</td>', 'Oh. My. As a make up artist- I''m instantly drawn to this image.  I realize this challenge was basic editing but I''m DYING to fix her brows, the smudge on the left eye, straighten the pencil...but enough about my OCD.  I love the lines of this image- the way she dominates the left hand side while the kohl liner takes my eye to the other edge of the image.  I like the way the ''blacks'' in this image all complement each.  Brows framing the eyes, outlined by the lashes all underlined by the pencil.  It works for me.  Well done.', '2011-07-03 23:32:15.000000', NULL, 1),
(6460168, 958306, 18778, '<td valign="top">First of all- a big ''o THANK YOU for doing something other than just a plain flower in this challenge.  This is classically beautiful to me.  Clean &amp; simple.</td>', 'First of all- a big ''o THANK YOU for doing something other than just a plain flower in this challenge.  This is classically beautiful to me.  Clean & simple.', '2011-07-03 23:36:38.000000', NULL, 1),
(6460171, 958661, 18778, '<td valign="top">I''m really really wanting to like this image.  But the focus?  And I know in this HK challenge- it''s a fine line, but it feels blown out a bit to me..</td>', 'I''m really really wanting to like this image.  But the focus?  And I know in this HK challenge- it''s a fine line, but it feels blown out a bit to me..', '2011-07-03 23:38:08.000000', NULL, 1),
(6460176, 959235, 18778, '<td valign="top">Oh man.  No doubt, you have done a good job of capturing a real emotion here... like an outtake from ''Toddlers &amp; Tiaras'' :(  I need a hug now.</td>', 'Oh man.  No doubt, you have done a good job of capturing a real emotion here... like an outtake from ''Toddlers & Tiaras'' :(  I need a hug now.', '2011-07-03 23:46:05.000000', NULL, 1),
(6460196, 959212, 18778, '<td valign="top">I love the movement here.  It feels like a still from a film.  Well done.</td>', 'I love the movement here.  It feels like a still from a film.  Well done.', '2011-07-03 23:49:04.000000', NULL, 1),
(6460270, 959305, 18778, '<td valign="top">This is one of the few ''just a flower entries'' I rated highly.  I love it.  The textures here are outstanding &amp; I love this barely there shade of pink.</td>', 'This is one of the few ''just a flower entries'' I rated highly.  I love it.  The textures here are outstanding & I love this barely there shade of pink.', '2011-07-04 00:09:03.000000', NULL, 1),
(6460306, 959180, 121949, '<td valign="top">My favorite of the challenge. The colors are just amazing.</td>', 'My favorite of the challenge. The colors are just amazing.', '2011-07-04 00:41:03.000000', NULL, 1),
(6460310, 959245, 121949, '<td valign="top">This is really well done. I wish I knew how to keep the detail in my highlights like this.</td>', 'This is really well done. I wish I knew how to keep the detail in my highlights like this.', '2011-07-04 00:41:45.000000', NULL, 1),
(6460311, 959305, 121949, '<td valign="top">Really beautiful, just like a ruffled dress</td>', 'Really beautiful, just like a ruffled dress', '2011-07-04 00:42:22.000000', NULL, 1),
(6460314, 958065, 121949, '<td valign="top">I love the colors in this photo, really clever to turn it upside down. It took me a minute but I eventually figured it out.</td>', 'I love the colors in this photo, really clever to turn it upside down. It took me a minute but I eventually figured it out.', '2011-07-04 00:43:14.000000', NULL, 1),
(6460315, 958230, 30049, '<td valign="top">Sorry, but I''m finding the subject somewhat uninteresting and the attempt at getting a high key effect ended up seeming to be more of a photo needing contrast and levels adjustments.  Was there a filter applied in post or something?</td>', 'Sorry, but I''m finding the subject somewhat uninteresting and the attempt at getting a high key effect ended up seeming to be more of a photo needing contrast and levels adjustments.  Was there a filter applied in post or something?', '2011-07-04 00:43:30.000000', NULL, 1),
(6460316, 959184, 121949, '<td valign="top">I''m guessing this is some sort of sheer fabric, it gives a really nice effect. Great job.</td>', 'I''m guessing this is some sort of sheer fabric, it gives a really nice effect. Great job.', '2011-07-04 00:43:52.000000', NULL, 1),
