(6461014, 959017, 58634, '<td valign="top">I like the play on words and the soft pink colors.</td>', 'I like the play on words and the soft pink colors.', '2011-07-04 14:44:03.000000', NULL, 1),
(6461015, 959298, 58634, '<td valign="top">I really like how vivid the greens look.</td>', 'I really like how vivid the greens look.', '2011-07-04 14:44:30.000000', NULL, 1),
