(6461027, 959055, 58634, '<td valign="top">IS THAT A PONY!? :O<br/>I''m too distracted by the cuteness of that to judge this image ;) lol</td>', 'IS THAT A PONY!? :OI''m too distracted by the cuteness of that to judge this image ;) lol', '2011-07-04 15:01:53.000000', NULL, 1),
(6461028, 958388, 58634, '<td valign="top">I like all the shapes in this picture. All the motion makes for a very unique, abstract image.</td>', 'I like all the shapes in this picture. All the motion makes for a very unique, abstract image.', '2011-07-04 15:02:41.000000', NULL, 1),
(6461029, 958071, 58634, '<td valign="top">A very lovely portrait. I kind of wish for a bit more contrast in her eyes to really make them stand out.</td>', 'A very lovely portrait. I kind of wish for a bit more contrast in her eyes to really make them stand out.', '2011-07-04 15:04:27.000000', NULL, 1),
